# SK414 — supAd (m.): su + pAd compound. SK414 (6.4.130) shortens pAd → pad when anga is bha
# (non-sarvānāmasthāna, vowel-initial sups). Sarvānāmasthāna (su/O/jas/am/Ow) retain supAd base.
# d at pada-end → t (8.2.39); d before voiced cons → d retained.
prAtipadika["supAd"] = [su_purva, in_compound(pAd_ut)]   # noqa: F405
viBakti["supAd"] = [
    [["सुपात्", "सुपाद्"], "सुपादौ", "सुपादः"],  # 1 Nom  * sarv: no SK414; d→t/d at pause; pl: d+as→daḥ
    ["सुपादम्", "सुपादौ", "सुपदः"],              # 2 Acc  * am/Ow sarv; acc pl Sas: bha→SK414
    ["सुपदा", "सुपाद्भ्याम्", "सुपाद्भिः"],       # 3 Inst * inst sg: bha→SK414; cons-initial: no SK414
    ["सुपदे", "सुपाद्भ्याम्", "सुपाद्भ्यः"],      # 4 Dat  * dat sg Ne: bha→SK414
    ["सुपदः", "सुपाद्भ्याम्", "सुपाद्भ्यः"],      # 5 Abl  * abl sg Nasi: bha→SK414
    ["सुपदः", "सुपदोः", "सुपदाम्"],              # 6 Gen  * gen sg/du/pl all bha→SK414
    ["सुपदि", "सुपदोः", "सुपात्सु"],              # 7 Loc  * loc sg Ni: bha→SK414; loc pl: d→t
    [["सुपात्", "सुपाद्"], "सुपादौ", "सुपादः"],  # 8 Voc  * = Nom
]

# SK456 (4.1.7 वनो र च) — full derivation chain test:
#   Sf + vanip → SK2168 (7.3.84) guṇa → Sar+van → join (van tag propagates) = Sarvan
#   Sarvan + strI_abs → SK456 NIp + n→r → SarvarI, then nadī-style ī-stem inflection.
# Every cell also produces an alternative geminated form via SK 8.4.46 (aco rahAbhyāṃ dve,
# optional) — Sar | van → Sar | vvan → Sarvvan → SarvvarI etc. Both are valid; we accept both.
prAtipadika["Sf_vanip_strI"] = [Sf, vanip, strI_abs]   # noqa: F405
viBakti["Sf_vanip_strI"] = [
    [["शर्वरी",      "शर्व्वरी"],      ["शर्वर्यौ",    "शर्व्वर्यौ"],    ["शर्वर्यः",   "शर्व्वर्यः"]],    # 1 Nom
    [["शर्वरीम्",    "शर्व्वरीम्"],    ["शर्वर्यौ",    "शर्व्वर्यौ"],    ["शर्वरीः",    "शर्व्वरीः"]],    # 2 Acc
    [["शर्वर्या",    "शर्व्वर्या"],    ["शर्वरीभ्याम्", "शर्व्वरीभ्याम्"], ["शर्वरीभिः",  "शर्व्वरीभिः"]],  # 3 Ins
    [["शर्वर्यै",    "शर्व्वर्यै"],    ["शर्वरीभ्याम्", "शर्व्वरीभ्याम्"], ["शर्वरीभ्यः", "शर्व्वरीभ्यः"]], # 4 Dat
    [["शर्वर्याः",   "शर्व्वर्याः"],   ["शर्वरीभ्याम्", "शर्व्वरीभ्याम्"], ["शर्वरीभ्यः", "शर्व्वरीभ्यः"]], # 5 Abl
    [["शर्वर्याः",   "शर्व्वर्याः"],   ["शर्वर्योः",   "शर्व्वर्योः"],   ["शर्वरीणाम्",  "शर्व्वरीणाम्"]], # 6 Gen
    [["शर्वर्याम्",  "शर्व्वर्याम्"],  ["शर्वर्योः",   "शर्व्वर्योः"],   ["शर्वरीषु",   "शर्व्वरीषु"]],   # 7 Loc
    [["शर्वरि",      "शर्व्वरि"],      ["शर्वर्यौ",    "शर्व्वर्यौ"],    ["शर्वर्यः",   "शर्व्वर्यः"]],   # 8 Voc
]

# SK457 (4.1.8 पादोऽन्यतरस्याम्) — pāda-final compound feminine, optional NIp test:
#   [dvi (as_purva_pada) | luk_sup | pAd_ut (in_compound) | strI_abs]
#   SK457 fires optionally → two paradigms:
#     A) NIp branch: dvipad+I → dvipadī etc. (bha triggers SK414 pAd→pad)
#     B) No-NIp branch: dvipAd halanta, same as supAd masculine but feminine
# Many cells produce both branches; nom/voc sg additionally produce dvipāt/dvipād pause variants.
prAtipadika["dvipAd_strI"] = [as_purva_pada(dvi), luk_sup, in_compound(pAd_ut), strI_abs]   # noqa: F405
viBakti["dvipAd_strI"] = [
    [["द्विपात्", "द्विपाद्", "द्विपदी"], ["द्विपादौ", "द्विपद्यौ"],     ["द्विपादः", "द्विपद्यः"]],   # 1 Nom
    [["द्विपादम्", "द्विपदीम्"],          ["द्विपादौ", "द्विपद्यौ"],     ["द्विपदः",  "द्विपदीः"]],   # 2 Acc
    [["द्विपदा",   "द्विपद्या"],          ["द्विपाद्भ्याम्", "द्विपदीभ्याम्"], ["द्विपाद्भिः", "द्विपदीभिः"]],  # 3 Ins
    [["द्विपदे",   "द्विपद्यै"],          ["द्विपाद्भ्याम्", "द्विपदीभ्याम्"], ["द्विपाद्भ्यः", "द्विपदीभ्यः"]], # 4 Dat
    [["द्विपदः",   "द्विपद्याः"],         ["द्विपाद्भ्याम्", "द्विपदीभ्याम्"], ["द्विपाद्भ्यः", "द्विपदीभ्यः"]], # 5 Abl
    [["द्विपदः",   "द्विपद्याः"],         ["द्विपदोः",      "द्विपद्योः"],     ["द्विपदाम्",   "द्विपदीनाम्"]], # 6 Gen
    [["द्विपदि",   "द्विपद्याम्"],        ["द्विपदोः",      "द्विपद्योः"],     ["द्विपात्सु",  "द्विपदीषु"]],   # 7 Loc
    [["द्विपात्", "द्विपाद्", "द्विपदि"], ["द्विपादौ",      "द्विपद्यौ"],      ["द्विपादः",    "द्विपद्यः"]],  # 8 Voc
]

# samAsa category dict — identifies compound test keys (kept separate from ajanta/halanta)
# SK307 negative test: Sūrpa + naKī compound → SūrpanaKī
# The compound has ?samasta_pada after merge, so 8.4.1/8.4.2 Ratva must NOT fire.
# Expected: regular ī-stem inflection with Sūrpa- prefix, no Ratva.
prAtipadika["SUrpanaKI"] = [as_purva_pada(SUrpa), luk_sup, in_compound(naKI)]   # noqa: F405
viBakti["SUrpanaKI"] = [
    ["शूर्पनखी", "शूर्पनख्यौ", "शूर्पनख्यः"],                     # 1 Nom  ī-stem, no Ratva (न not ण)
    ["शूर्पनखीम्", "शूर्पनख्यौ", "शूर्पनखीः"],  # 2 Acc
    ["शूर्पनख्या", "शूर्पनखीभ्याम्", "शूर्पनखीभिः"],               # 3 Inst
    ["शूर्पनख्यै", "शूर्पनखीभ्याम्", "शूर्पनखीभ्यः"],              # 4 Dat
    ["शूर्पनख्याः", "शूर्पनखीभ्याम्", "शूर्पनखीभ्यः"],             # 5 Abl
    ["शूर्पनख्याः", "शूर्पनख्योः", "शूर्पनखीनाम्"],                # 6 Gen
    ["शूर्पनख्याम्", "शूर्पनख्योः", "शूर्पनखीषु"],                 # 7 Loc
    ["शूर्पनखि", "शूर्पनख्यौ", "शूर्पनख्यः"],                     # 8 Voc
]

# SK307 test: kṣīra + pa compound → kṣīrapā (like jYAna napum paradigm)
# SK307 (8.4.12): ekāc uttara-pada with n → ṇatva when pūrva has ratva cause (r/ṣ/ṛ).
# Ratva in nom/acc/voc pl, sg instr, gen pl; rest like jYAna
prAtipadika["kzIrapa"] = [as_purva_pada(kzIra), luk_sup, in_compound(pa)]   # noqa: F405
viBakti["kzIrapa"] = [
    ["क्षीरपम्", "क्षीरपे", "क्षीरपाणि"],                  # 1 Nom: sg jYAna, du jYAna, pl Ratva
    ["क्षीरपम्", "क्षीरपे", "क्षीरपाणि"],                  # 2 Acc: same as Nom (neuter)
    ["क्षीरपेण", "क्षीरपाभ्याम्", "क्षीरपैः"],             # 3 Instr: jYAna
    ["क्षीरपाय", "क्षीरपाभ्याम्", "क्षीरपेभ्यः"],          # 4 Dat: jYAna
    [["क्षीरपाद्", "क्षीरपात्"], "क्षीरपाभ्याम्", "क्षीरपेभ्यः"],  # 5 Abl
    ["क्षीरपस्य", "क्षीरपयोः", "क्षीरपाणाम्"],             # 6 Gen: sg/du jYAna, pl Ratva
    ["क्षीरपे", "क्षीरपयोः", "क्षीरपेषु"],                 # 7 Loc: jYAna
    ["क्षीरपम्", "क्षीरपे", "क्षीरपाणि"],                  # 8 Voc: same as Nom (neuter)
]

# samAsa category dict — identifies compound test keys (kept separate from ajanta/halanta)
# SK429/SK430 — tādṛk/tādṛśa forms: tyadAdi + dfS (dṛś) + kvin/kaY + SK430 (tad→tA)
# Base stem: tAdfS (तादृश्) — after SK430 (ā-substitution) + dfS + kvin/kaY
# kvin: j→g before bh (8.2.62); kaY: no j→g
# tAdfk (kvin): Nom sg has alternatives तादृक् / तादृग् (8.2.62 + 8.4.56 opt)
# tAdfSa (kaY): Nom sg is तादृशः (regular a-stem)

# tādṛk (m.) — [tad_pada in_compound(dfS) kvin]
prAtipadika["tAdfk"] = [tad, luk_sup, in_compound(dfS), kvin]   # noqa: F405
viBakti["tAdfk"] = [
    [['तादृक्', 'तादृग्'], 'तादृशौ', 'तादृशः'],    # 1 Nom  * kvin: 8.2.62 j→g, 8.4.56 opt g→k
    ['तादृशम्', 'तादृशौ', 'तादृशः'],                # 2 Acc
    ['तादृशा', 'तादृग्भ्याम्', 'तादृग्भिः'],       # 3 Inst * kvin: j→g before Bh
    ['तादृशे', 'तादृग्भ्याम्', 'तादृग्भ्यः'],       # 4 Dat
    ['तादृशः', 'तादृग्भ्याम्', 'तादृग्भ्यः'],       # 5 Abl
    ['तादृशः', 'तादृशोः', 'तादृशाम्'],            # 6 Gen
    ['तादृशि', 'तादृशोः', 'तादृक्षु'],             # 7 Loc  * pl: j→g→k+8.3.57→ṣ
    [['तादृक्', 'तादृग्'], 'तादृशौ', 'तादृशः'],    # 8 Voc  = Nom
]

# tādṛśa (m.) — [tad_pada in_compound(dfS) kaY] — kaY uses a-stem endings like rAma
prAtipadika["tAdfSa"] = [tad, luk_sup, in_compound(dfS), in_context(kaY, "pum")]   # noqa: F405
viBakti["tAdfSa"] = [
    ['तादृशः', 'तादृशौ', 'तादृशाः'],                # 1 Nom
    ['तादृशम्', 'तादृशौ', 'तादृशान्'],               # 2 Acc
    ['तादृशेन', 'तादृशाभ्याम्', 'तादृशैः'],          # 3 Inst
    ['तादृशाय', 'तादृशाभ्याम्', 'तादृशेभ्यः'],       # 4 Dat
    [['तादृशात्', 'तादृशाद्'], 'तादृशाभ्याम्', 'तादृशेभ्यः'],      # 5 Abl
    ['तादृशस्य', 'तादृशयोः', 'तादृशानाम्'],          # 6 Gen
    ['तादृशे', 'तादृशयोः', 'तादृशेषु'],              # 7 Loc
    ['तादृश', 'तादृशौ', 'तादृशाः'],                 # 8 Voc
]

# yādṛk (m.) — [yad, su, in_compound(dfS) kvin]
prAtipadika["yAdfk"] = [yad, su, in_compound(dfS), kvin]   # noqa: F405
viBakti["yAdfk"] = [
    [['यादृक्', 'यादृग्'], 'यादृशौ', 'यादृशः'],    # 1 Nom  * kvin: 8.2.62 j→g, 8.4.56 opt g→k
    ['यादृशम्', 'यादृशौ', 'यादृशः'],                # 2 Acc
    ['यादृशा', 'यादृग्भ्याम्', 'यादृग्भिः'],       # 3 Inst * kvin: j→g before Bh
    ['यादृशे', 'यादृग्भ्याम्', 'यादृग्भ्यः'],       # 4 Dat
    ['यादृशः', 'यादृग्भ्याम्', 'यादृग्भ्यः'],       # 5 Abl
    ['यादृशः', 'यादृशोः', 'यादृशाम्'],            # 6 Gen
    ['यादृशि', 'यादृशोः', 'यादृक्षु'],             # 7 Loc  * pl: j→g→k+8.3.57→ṣ
    [['यादृक्', 'यादृग्'], 'यादृशौ', 'यादृशः'],    # 8 Voc  = Nom
]

